'use client';
import { motion, useScroll, useTransform, AnimatePresence } from "framer-motion";
import { useRef, useState, useEffect } from "react";
import dynamic from "next/dynamic";

export default function PlantilirLanding() {
  const heroRef = useRef(null);
  const { scrollYProgress } = useScroll({ target: heroRef });
  const bgY = useTransform(scrollYProgress, [0, 1], ["0%", "30%"]);
  const hue = useTransform(scrollYProgress, [0, 1], [220, 300]);

  const [cursor, setCursor] = useState({ x: -9999, y: -9999 });
  const [theme, setTheme] = useState("dark");
  const [mounted, setMounted] = useState(false);



	// Lazy-load 3D model (React Three Fiber + Drei). Create a lightweight stylized model.
	const ModelViewer = dynamic(
		() => import("./PlantilirModel").catch(() => () => null),
		{ ssr: false }
	);

	function ThemeToggle({ theme, setTheme }:any) {
		return (
			<button
			aria-label="Toggle theme"
			onClick={() => setTheme(theme === "dark" ? "neon" : theme === "neon" ? "light" : "dark")}
			className="ml-4 px-3 py-2 rounded-full border border-white/20 bg-white/5 backdrop-blur transition-all hover:scale-105"
			>
			{theme === "dark" ? "Neon" : theme === "neon" ? "Light" : "Dark"}
			</button>
		);
	}

	function MagneticButton({ children, className = "", ...props }:any) {
		const ref = useRef(null);

		function handleMove(e:any) {
			const el = ref.current as any;
			if (!el) return;
			const rect = el.getBoundingClientRect();
			const x = e.clientX - rect.left - rect.width / 2;
			const y = e.clientY - rect.top - rect.height / 2;
			el.style.transform = `translate(${x * 0.12}px, ${y * 0.08}px) scale(1.03)`;
		}
		function reset() {
			const el = ref.current as any;
			if (!el) return;
			el.style.transform = "translate(0,0) scale(1)";
		}

		return (
			<button
			ref={ref}
			onMouseMove={handleMove}
			onMouseLeave={reset}
			{...props}
			className={
				"relative inline-block px-8 py-3 rounded-full border border-white/25 bg-white/10 backdrop-blur-md shadow-xl transition-transform will-change-transform " +
				className
			}
			>
			{children}
			</button>
		);
	}





  useEffect(() => setMounted(true), []);

  useEffect(() => {
	// update css variables for theme
	const root = document.documentElement;
	if (theme === "dark") {
	  root.style.setProperty("--accent", "220 90% 60%");
	  root.style.setProperty("--bg-blur", "12px");
	  root.style.setProperty("--glass-opacity", "0.10");
	} else if (theme === "neon") {
	  root.style.setProperty("--accent", "285 95% 52%");
	  root.style.setProperty("--bg-blur", "6px");
	  root.style.setProperty("--glass-opacity", "0.12");
	} else {
	  root.style.setProperty("--accent", "200 40% 40%");
	  root.style.setProperty("--bg-blur", "8px");
	  root.style.setProperty("--glass-opacity", "0.08");
	}
  }, [theme]);

  return (
	<AnimatePresence mode="wait">
	  <motion.div
		key="plantilir-landing"
		initial={{ opacity: 0 }}
		animate={{ opacity: 1 }}
		exit={{ opacity: 0 }}
		className="relative min-h-screen overflow-x-hidden bg-gradient-to-b from-slate-900 to-black text-white select-none"
		onMouseMove={(e) => setCursor({ x: e.clientX, y: e.clientY })}
	  >
		{/* custom CSS variables and global small styles */}
		<style>{`
		  :root{ --accent-h: 220; }
		  .accent-gradient{ background: linear-gradient(90deg, hsl(var(--accent)) , rgba(255,255,255,0.06)); }
		`}</style>

		{/* Dynamic cursor glow */}
		<div
		  aria-hidden
		  className="pointer-events-none fixed w-72 h-72 rounded-full bg-[radial-gradient(circle,rgba(255,255,255,0.12),transparent)] blur-3xl -translate-x-1/2 -translate-y-1/2 transition-transform duration-150"
		  style={{ left: cursor.x, top: cursor.y }}
		/>

		{/* Ambient floating orbs */}
		<motion.div
		  style={{ y: bgY }}
		  className="absolute -top-48 -left-48 w-96 h-96 rounded-full"
		  animate={{ background: "radial-gradient(circle, rgba(99,102,241,0.12), transparent)" }}
		  transition={{ duration: 12, repeat: Infinity }}
		/>
		<motion.div
		  style={{ y: bgY }}
		  className="absolute top-12 -right-40 w-[28rem] h-[28rem] rounded-full"
		  animate={{ background: "radial-gradient(circle, rgba(139,92,246,0.10), transparent)" }}
		  transition={{ duration: 16, repeat: Infinity }}
		/>

		{/* Top bar */}
		<header className="fixed top-6 left-6 right-6 z-50 flex items-center justify-between">
		  <div className="flex items-center gap-4">
			<div className="w-10 h-10 rounded-xl bg-white/5 border border-white/10 flex items-center justify-center">PL</div>
			<div className="hidden sm:block text-sm opacity-90">Plantilir</div>
		  </div>

		  <div className="flex items-center">
			<ThemeToggle theme={theme} setTheme={setTheme} />
		  </div>
		</header>

		{/* HERO */}
		<section ref={heroRef} className="relative flex flex-col items-center justify-center h-screen text-center px-6">
		  {/* 3D Model Behind Hero */}
		  <div className="absolute inset-0 opacity-30 pointer-events-none z-0">
			{mounted && <ModelViewer />}
		  </div>

		  <motion.div
			initial={{ opacity: 0, scale: 0.96 }}
			animate={{ opacity: 1, scale: 1 }}
			transition={{ duration: 0.9 }}
			className="relative z-10 backdrop-blur-[var(--bg-blur)] bg-white/var(--glass-opacity) border border-white/10 rounded-3xl p-12 shadow-2xl max-w-4xl"
			style={{ boxShadow: "0 10px 40px rgba(2,6,23,0.6)" }}
		  >
			<motion.h1
			  initial={{ y: 60, opacity: 0 }}
			  animate={{ y: 0, opacity: 1 }}
			  transition={{ duration: 1, ease: "easeOut" }}
			  className="text-6xl sm:text-7xl font-bold mb-4 tracking-tight"
			>
			  Plantilir
			</motion.h1>

			<motion.p
			  initial={{ y: 40, opacity: 0 }}
			  animate={{ y: 0, opacity: 1 }}
			  transition={{ duration: 1, delay: 0.18 }}
			  className="text-lg opacity-90 max-w-2xl mx-auto leading-relaxed"
			>
			  Connect with anyone alive — where AI meets high-fidelity networking.
			</motion.p>

			<div className="mt-8 flex items-center justify-center gap-4">
				<a href="./sign">
					<MagneticButton className="accent-gradient" onClick={() => alert("Enter network clicked")}>Enter the Network</MagneticButton>
					<MagneticButton onClick={() => alert("Learn more clicked")} className="bg-white/5">Learn more</MagneticButton>
				</a>
			</div>
		  </motion.div>
		</section>

		{/* ===== PARALLAX IMAGE SHOWCASE WITH SCROLL COLOR SHIFT ===== */}
		<section className="relative py-32 px-6">
		  <h2 className="text-4xl font-semibold text-center mb-12">People. Movement. Style.</h2>

		  <div className="max-w-6xl mx-auto grid grid-cols-1 md:grid-cols-3 gap-10">
			{[
			  "https://images.unsplash.com/photo-1492551557933-34265f7af79e?auto=format&fit=crop&w=1200&q=80",
			  "https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=1200&q=80",
			  "https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=1200&q=80",
			].map((src, i) => (
			  <motion.div
				key={i}
				initial={{ opacity: 0, y: 60 }}
				whileInView={{ opacity: 1, y: 0 }}
				viewport={{ once: true }}
				transition={{ duration: 0.9, delay: i * 0.2 }}
				className="relative h-72 sm:h-96 rounded-3xl overflow-hidden shadow-2xl bg-black/10"
				style={{ border: "1px solid rgba(255,255,255,0.04)" }}
			  >
				<motion.img
				  src={src}
				  className="w-full h-full object-cover transform-gpu transition-transform will-change-transform"
				  style={{ transformOrigin: "center" }}
				  animate={{ scale: [1.06, 1.0, 1.06] }}
				  transition={{ duration: 12, repeat: Infinity }}
				/>
				<div className="absolute inset-0 bg-gradient-to-t from-black/50 to-transparent" />
				<div className="absolute left-6 bottom-6 text-white">
				  <div className="text-sm opacity-90">Creative • Network</div>
				  <div className="text-xl font-semibold">Style Series {i + 1}</div>
				</div>
			  </motion.div>
			))}
		  </div>
		</section>

		{/* ===== FEATURES SECTION with subtle transitions ===== */}
		<section className="relative py-24 px-6">
		  <div className="max-w-5xl mx-auto grid grid-cols-1 md:grid-cols-3 gap-8">
			{[
			  { title: "Global Reach", body: "Find and connect with professionals across every industry and continent." },
			  { title: "Curated Style", body: "Aesthetic-first profiles that feel like a magazine — minimal, expressive, powerful." },
			  { title: "High-Fidelity", body: "Rich profiles and real-time interactions crafted for performance." },
			].map((f, i) => (
			  <motion.div
				key={i}
				initial={{ opacity: 0, y: 20 }}
				whileInView={{ opacity: 1, y: 0 }}
				viewport={{ once: true }}
				transition={{ delay: i * 0.15 }}
				className="backdrop-blur-[var(--bg-blur)] bg-white/var(--glass-opacity) border border-white/10 rounded-2xl p-8 shadow"
			  >
				<div className="text-2xl font-semibold mb-3">{f.title}</div>
				<div className="opacity-90 text-sm leading-relaxed">{f.body}</div>
			  </motion.div>
			))}
		  </div>
		</section>

		{/* ===== FINAL CTA with page transition style ===== */}
		<section className="relative py-40 text-center px-6">
		  <motion.div
			initial={{ opacity: 0, y: 20 }}
			whileInView={{ opacity: 1, y: 0 }}
			viewport={{ once: true }}
			transition={{ duration: 0.8 }}
			className="relative z-10 backdrop-blur-xl bg-white/var(--glass-opacity) border border-white/20 p-16 rounded-3xl max-w-3xl mx-auto shadow-2xl"
		  >
			<h2 className="text-4xl sm:text-5xl font-semibold mb-6 tracking-tight">Step Into the Global Fabric</h2>
			<p className="text-lg opacity-90 max-w-xl mx-auto mb-10">
			  AI meets connection. A clean, modern network for a clean, modern world.
			</p>

			<div className="flex items-center justify-center gap-4">
			  <MagneticButton className="accent-gradient" onClick={() => alert('Join clicked')}>Join Plantilir</MagneticButton>
			  <MagneticButton>Contact</MagneticButton>
			</div>
		  </motion.div>
		</section>

		<footer className="text-center py-12 opacity-70 text-sm">© {new Date().getFullYear()} Plantilir — All rights reserved</footer>
	  </motion.div>
	</AnimatePresence>
  );
}

/*
  NOTES:
  - This file expects a sibling file at ./components/PlantilirModel.jsx which exports a default React component using @react-three/fiber and @react-three/drei.
  - Tailwind CSS (with backdrop-filter), Framer Motion, React Three Fiber, and Drei should be installed.
  - The ThemeToggle cycles themes: dark -> neon -> light. CSS variables are used for quick theming.
  - MagneticButton implements a subtle magnetic micro-interaction.
  - Page transitions are implemented with AnimatePresence; use in Next.js _app to animate route changes similarly.
*/